mapper.update:
UPDATE browse_history
SET visited_at = #{visitedAt}
WHERE user_id = #{userId}
  AND product_id = #{productId}

mapper.select:
SELECT history_id, user_id, product_id, visited_at
FROM browse_history
WHERE user_id = #{userId}
  AND product_id = #{productId}

SELECT history_id, user_id, product_id, visited_at
FROM browse_history
WHERE user_id = #{userId}
ORDER BY visited_at DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM browse_history
WHERE user_id = #{userId}
  AND product_id = #{productId}
